/* Loading the recompiled modules into host memory (decisions 0010, 0014).
 *
 * The tables below are generated by recomp.translate (work/recomp/image_info.c) from the
 * owner's main and sdk; the image bytes themselves are read from disk at start-up, never
 * built in. Symbols are already resolved at translation time (load order main, sdk).
 */
#ifndef YW4LOAD_H
#define YW4LOAD_H

#include <stddef.h>
#include <stdint.h>

#include "yw4rt.h"

/* R_AARCH64_RELATIVE: *(base + offset) = base + addend */
typedef struct {
    uint64_t offset;
    int64_t addend;
} Yw4Relative;

/* ABS64 / GLOB_DAT / JUMP_SLOT, resolved: *(base + offset) = base of `module` + value,
 * or 0 for module = YW4_NO_MODULE (weak symbols nobody defines). */
typedef struct {
    uint64_t offset;
    uint32_t module;
    uint64_t value;
} Yw4SymReloc;

enum { YW4_MAIN = 0, YW4_SDK = 1, YW4_NO_MODULE = 0xFFFFFFFFu };

typedef struct {
    const char *name;
    const char *file;           /* in the exefs work directory */
    const char *sha256;         /* of the flat image: the version lock */
    uint64_t file_size, mem_size, preferred_base;
    uint64_t *base;             /* set by the loader */
    const Yw4Relative *relative;
    size_t nrelative;
    const Yw4SymReloc *symrelocs;
    size_t nsymrelocs;
    uint64_t dt_init;           /* offset of DT_INIT (registers the module, runs its constructors) */
    uint64_t ro_offset, data_offset;  /* .text is [0, ro), .rodata [ro, data), .data + .bss [data, mem_size) */
} Yw4Module;

/* Generated */
extern const Yw4Module yw4_modules[];
extern const size_t yw4_nmodules;
extern const uint64_t yw4_entry_init_start;  /* sdk offset of nn::init::Start */
extern const uint64_t yw4_main_stack_size;    /* from the NPDM */
extern const uint32_t yw4_main_priority;

/* Runtime: the guest address space (decision 0014), all inside the 39-bit space games may
 * assume. The kernel reports these regions through svcGetInfo. */
#define YW4_GUEST_LO 0x7000000000ull
#define YW4_GUEST_HI 0x7800000000ull
#define YW4_STACK_BASE 0x7000000000ull      /* guest stacks */
#define YW4_STACK_SIZE 0x0040000000ull
#define YW4_TLR_BASE 0x7040000000ull        /* thread-local regions (TPIDRRO_EL0) */
#define YW4_HOST_FN_BASE 0x7080000000ull    /* guest addresses of host callbacks */
#define YW4_HEAP_BASE 0x7200000000ull       /* svcSetHeapSize: reserved, committed as it grows */
#define YW4_HEAP_SIZE 0x0180000000ull
#define YW4_ALIAS_BASE 0x7400000000ull      /* svcMapMemory targets */
#define YW4_ALIAS_SIZE 0x0100000000ull

/* Zeroed read/write memory, at `want` if that range is free (0 = anywhere), else anywhere. */
void *yw4_reserve(uint64_t want, size_t size);
/* Address space only, at exactly `want` (NULL if taken); yw4_commit makes parts of it
 * usable (zeroed), yw4_decommit gives memory back. */
void *yw4_reserve_range(uint64_t want, size_t size);
int yw4_commit(uint64_t addr, size_t size);
void yw4_reserve_free(uint64_t lo, uint64_t hi);  /* see loader.c */
void yw4_decommit(uint64_t addr, size_t size);
/* Sleeps the calling host thread (no-op for ns <= 0). */
void yw4_host_sleep_ns(int64_t ns);

/* Reads, verifies (size + SHA-256) and relocates every module from `exefs_dir`. Returns 0 on
 * success; prints why not. */
int yw4_load_modules(const char *exefs_dir);

/* A guest address that, when called, runs `fn` on the calling guest thread. */
uint64_t yw4_host_function(GuestFn fn);
/* The same, with a pointer `fn` gets back from yw4_host_data(): one host function can then
 * stand behind many addresses. Read it first thing, before calling any guest code. */
uint64_t yw4_host_function_data(GuestFn fn, void *data);
void *yw4_host_data(void);

/* SHA-256 of a buffer as 64 lowercase hex digits + NUL. */
void yw4_sha256_hex(const uint8_t *data, size_t len, char out[65]);

#endif
